def average_by_welford(nums):
    """通过 Welford 在线算法逐步更新平均值。"""
    if not nums:
        raise ValueError("列表不能为空")
    mean = 0.0
    for count, x in enumerate(nums, 1):
        mean += (x - mean) / count
    return mean

