def can_permute_palindrome_A(s: str) -> bool:
    counter = {}
    for ch in s.lower():
        if ch.isalnum():
            counter[ch] = counter.get(ch, 0) + 1
    odd_count = sum(1 for v in counter.values() if v % 2 == 1)
    return odd_count <= 1

