def calculate_electricity_bill_B(x):
    return (
        0.5 * x
        + 0.15 * max(0, min(x, 400) - 200)
        + 0.40 * max(0, x - 400)
    )

def most_frequent_order(orders):
    if not orders:
        return None
    count = {}
    for order in orders:
        count[order] = count.get(order, 0) + 1
    max_count = max(count.values())
    return min((order for order, c in count.items() if c == max_count), key=lambda x: int(x))

def count_words_with_regex(text):
    import re
    counts = {}
    for word in re.findall(r'[a-z]+', text.lower()):
        counts[word] = counts.get(word, 0) + 1
    return counts


def count_words_with_state_machine(text):
    counts = {}
    buf = []
    for ch in text:
        if ('a' <= ch <= 'z') or ('A' <= ch <= 'Z'):
            buf.append(ch.lower())
        else:
            if buf:
                word = ''.join(buf)
                counts[word] = counts.get(word, 0) + 1
                buf = []
    if buf:
        word = ''.join(buf)
        counts[word] = counts.get(word, 0) + 1
    return counts

def is_valid_ipv4(s: str) -> bool:
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not all('0' <= c <= '9' for c in part):
            return False
        if int(part) > 255:
            return False
    return True

def is_palindrome(s: str) -> bool:
    left, right = 0, len(s) - 1
    while left < right:
        while left < right and not s[left].isalnum():
            left += 1
        while left < right and not s[right].isalnum():
            right -= 1
        if left < right:
            if s[left].lower() != s[right].lower():
                return False
            left += 1
            right -= 1
    return True

def is_palindrome_permutation(s: str) -> bool:
    mask = 0
    for ch in s:
        if ch.isalpha():
            bit = 1 << (ord(ch.lower()) - ord('a'))
            mask ^= bit
    return mask == 0 or (mask & (mask - 1)) == 0

def required_workdays(order_qty, stock_qty, daily_output):
    if stock_qty >= order_qty:
        return 0
    shortage = order_qty - stock_qty
    return (shortage + daily_output - 1) // daily_output

def sort_words_by_length(sentence):
    words = sentence.split()
    if not words:
        return []
    max_len = max(len(w) for w in words)
    buckets = [[] for _ in range(max_len + 1)]
    for word in words:
        buckets[len(word)].append(word)
    return [word for bucket in buckets for word in bucket]

def is_valid_isbn10(isbn):
    if not isinstance(isbn, str):
        return False
    s = isbn.replace('-', '').upper()
    if len(s) != 10:
        return False
    if not s[:9].isdigit():
        return False

    total = 0
    for i, ch in enumerate(s):
        if ch == 'X':
            v = 10
        elif ch.isdigit():
            v = int(ch)
        else:
            return False
        total += v * (10 - i)

    return total % 11 == 0

def calculate_training_fee(hours, level):
    if level == '初级':
        rate = 100
    elif level == '高级':
        rate = 180
    else:
        raise ValueError("教师等级必须是初级或高级")

    original = hours * rate
    extra = max(0, hours - 20)
    discount = extra * rate * 0.2
    return original - discount

def is_secure_password(password: str) -> bool:
    if len(password) < 8:
        return False
    has_letter = False
    has_digit = False
    for ch in password:
        if ('a' <= ch <= 'z') or ('A' <= ch <= 'Z'):
            has_letter = True
        elif '0' <= ch <= '9':
            has_digit = True
    return has_letter and has_digit

